/*
 Problem: 1032. Stream of Characters
 Language: cpp
 Runtime: 108 ms (82.52%)
 Memory: 262.8 MB (55.32%)
 Tags: Array, String, Design, Trie, Data Stream, Aho–Corasick Algorithm
*/
class StreamChecker {
    struct Node {
        Node* child[26]{};
        bool isWord = false;
    };

    Node* root = new Node();
    string stream;

public:
    StreamChecker(vector<string>& words) {
        for (string& word : words) {
            reverse(word.begin(), word.end());

            Node* cur = root;
            for (char c : word) {
                int i = c - 'a';
                if (!cur->child[i])
                    cur->child[i] = new Node();
                cur = cur->child[i];
            }

            cur->isWord = true;
        }
    }

    bool query(char letter) {
        stream += letter;

        Node* cur = root;

        for (int i = stream.size() - 1; i >= 0; --i) {
            int idx = stream[i] - 'a';

            if (!cur->child[idx])
                return false;

            cur = cur->child[idx];

            if (cur->isWord)
                return true;
        }

        return false;
    }
};

/**
 * Your StreamChecker object will be instantiated and called as such:
 * StreamChecker* obj = new StreamChecker(words);
 * bool param_1 = obj->query(letter);
 */
